set +e
# flash1-undo (generated by bltorch-20261114/make_guests.py from block-*.py; see those files for what and why)
fsck.hfsplus -f -n /dev/vda | tail -2
mount -t hfsplus -o rw,force /dev/vda /work/root || exit 1
python3 - <<'GUEST'
UNDO=True
# flash1: MobileGestalt's cached "camera-flash" answer -> true (Control Center flashlight; q10jch run 2026-11-13, kernel 0496 + 0502).
# Control Center drops FlashlightModule.bundle because its Info.plist requires the capability "camera-flash"; AVFlashlight asks the
# same question. libMobileGestalt (20H392) answers it from IODeviceTree:/product/camera property "flash" (function 0x19c563598) --
# a node this port's device tree did not have (kernel 0502 makes it) -- but only when the answer is not in its cache file:
# MGCopyAnswer first looks in CacheData (sub_19c557110: 594 slots of 8 bytes, then one "valid" byte per slot at 0x1290; the slot
# number is the u16 at +0x9a of the key's table entry). "camera-flash" is slot 0x3f and the cache made on this phone holds
# valid=1 value=0, so the new device-tree node alone would change nothing.
# This block sets that one value byte to 1 (the file keeps its size, owner and mode; nothing else in it changes). It refuses a
# cache of another build/layout, and does nothing when the slot is not valid (then the kernel's node answers) or already 1.
# Receipt /private/var/db/nord2-stock/flash1.json (offset, old byte, sha before/after); the undo puts the old byte back.
# Idempotent; FLASH1_REFUSED = no change.
import os, json, hashlib, plistlib
R='/work/root'
MG='/private/var/containers/Shared/SystemGroup/systemgroup.com.apple.mobilegestaltcache/Library/Caches/com.apple.MobileGestalt.plist'
D='/private/var/db/nord2-stock'; REC=D+'/flash1.json'
SLOT=0x3f; SLOTS=594; VALID=0x1290; LEN=0x14e2; BUILD='20H392'; UUID='42F6FA57-C5A1-4134-9BF4-AB00F962EAE8'
sha=lambda b: hashlib.sha256(b).hexdigest(); rd=lambda p: open(R+p,'rb').read()
def put(path, data, mode, uid, gid):
    tmp=R+path+'.nord2tmp'
    if os.path.lexists(tmp): os.remove(tmp)
    with open(tmp,'xb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
    os.chmod(tmp,mode); os.chown(tmp,uid,gid); os.replace(tmp,R+path)
    assert rd(path)==data
def locate(raw):
    """-> (offset of CacheData in the file, why not)"""
    try: p=plistlib.loads(raw)
    except Exception as e: return None,'not a property list (%s)'%type(e).__name__
    if not isinstance(p,dict) or p.get('CacheVersion')!=BUILD or p.get('CacheUUID')!=UUID: return None,'cache of another build (%r %r)'%(p.get('CacheVersion') if isinstance(p,dict) else None, p.get('CacheUUID') if isinstance(p,dict) else None)
    d=p.get('CacheData')
    if not isinstance(d,bytes) or len(d)!=LEN or LEN!=VALID+SLOTS: return None,'CacheData is not the 20H392 layout'
    if raw[:6]!=b'bplist' or raw.count(d)!=1: return None,'CacheData not found once as raw bytes (not a binary property list?)'
    return raw.find(d),None
def write_rec(rec):
    os.makedirs(R+D,exist_ok=True)
    with open(R+REC,'w') as f: json.dump(rec,f,indent=1); f.flush(); os.fsync(f.fileno())
rec=json.load(open(R+REC)) if os.path.exists(R+REC) else None
if not os.path.isfile(R+MG):
    if UNDO and rec is not None:
        os.remove(R+REC)
        if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
        print('FLASH1_UNDO the cache file is gone (it will be made again from the device tree): receipt removed')
    else: print('FLASH1_UNDO nothing to undo' if UNDO else 'FLASH1_INSTALL no cache file: MobileGestalt will ask the device tree (kernel 0502), nothing to change')
else:
    raw=rd(MG); off,why=locate(raw); st=os.stat(R+MG)
    if off is None: print('FLASH1_REFUSED', why)
    else:
        v=off+SLOT*8; valid=raw[off+VALID+SLOT]; cur=raw[v:v+8]
        if not UNDO:
            if rec is not None and cur[0]==1: print('FLASH1_INSTALL already (camera-flash cached true, receipt present)')
            elif rec is not None: print('FLASH1_REFUSED receipt present but the cached answer is', cur.hex(), 'valid', valid, ': undo first')
            elif not valid: print('FLASH1_INSTALL camera-flash is not in the cache (valid 0): the device tree answers, nothing to change')
            elif cur[0]==1: print('FLASH1_INSTALL camera-flash already cached true (no receipt): nothing to change')
            elif cur!=bytes(8): print('FLASH1_REFUSED unexpected cached value', cur.hex())
            else:
                new=raw[:v]+b'\x01'+raw[v+1:]
                rec={'by':'bltorch-20261114 flash1','path':MG,'file_offset':v,'slot':SLOT,'old_byte':cur[0],'new_byte':1,'sha_before':sha(raw),'sha_after':sha(new)}
                write_rec(rec)
                put(MG,new,st.st_mode&0o7777,st.st_uid,st.st_gid)
                a=plistlib.loads(raw); b=plistlib.loads(new); da=a.pop('CacheData'); db=b.pop('CacheData')
                assert a==b and len(da)==len(db) and [i for i in range(LEN) if da[i]!=db[i]]==[SLOT*8]
                print('FLASH1_INSTALL camera-flash cached answer 0 -> 1 (slot 0x%x, file offset %d, %d bytes, sha %s -> %s)'%(SLOT,v,len(new),sha(raw)[:12],sha(new)[:12]))
        else:
            if rec is None: print('FLASH1_UNDO nothing to undo')
            elif cur[0]!=rec['new_byte']:
                os.remove(R+REC)
                if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
                print('FLASH1_UNDO the cached answer is', cur.hex(), '(not ours any more): receipt removed, file left as it is')
            else:
                new=raw[:v]+bytes([rec['old_byte']])+raw[v+1:]
                put(MG,new,st.st_mode&0o7777,st.st_uid,st.st_gid)
                os.remove(R+REC)
                if os.path.isdir(R+D) and not os.listdir(R+D): os.rmdir(R+D)
                print('FLASH1_UNDO camera-flash cached answer 1 -> %d byte_identical_to_before=%s'%(rec['old_byte'],sha(new)==rec['sha_before']))
os.sync()
GUEST
echo 'CC_JOB_ADDED flash1-undo'
echo 'CC_RECEIPT_UPDATED unchanged'
sync
umount /work/root
fsck.hfsplus -f -n /dev/vda
echo INSTALL_DONE
